// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address a, uint256) public {
        vm.assume(a != address(0));

        if (c.tokenBalance(a) != 0) return;

        CallerHelper helper = new CallerHelper(c);

        address helperAddr = address(helper);
        if (c.tokenBalance(helperAddr) != 0) return;

        helper.callAirDrop();

        assertTrue(c.tokenBalance(helperAddr) == 20);
    }
}

contract CallerHelper {
    ModifierEntrancy immutable c;
    constructor(ModifierEntrancy _c) { c = _c; }
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop() external {
        c.airDrop();
    }
}
